use xiom.io;

fn main() -> Int {
  let name = io.read_line();
  io.println("Hello, " + name + "!");

  let age = io.read_int();
  match age {
    Ok(value) => { io.println("You are " + value.to_str() + "."); }
    Err(message) => { io.println("I could not read the age: " + message); }
  }
  return 0;
}
